```sql
CREATE PROCEDURE faire_virement(
    IN p_source INT,
    IN p_destination INT,
    IN p_montant DECIMAL
)
LANGUAGE plpgsql
AS $$
BEGIN
    -- Démarrer la transaction
    BEGIN;

    -- Vérifier que le compte source existe
    IF NOT EXISTS (SELECT 1 FROM comptes WHERE id_compte = p_source) THEN
        RAISE EXCEPTION 'Compte source inexistant';
    END IF;

    -- Vérifier que le compte destination existe
    IF NOT EXISTS (SELECT 1 FROM comptes WHERE id_compte = p_destination) THEN
        RAISE EXCEPTION 'Compte destination inexistant';
    END IF;

    -- Vérifier le solde
    IF (SELECT solde FROM comptes WHERE id_compte = p_source) < p_montant THEN
        RAISE EXCEPTION 'Solde insuffisant';
    END IF;

    -- Effectuer le virement
    UPDATE comptes SET solde = solde - p_montant WHERE id_compte = p_source;
    UPDATE comptes SET solde = solde + p_montant WHERE id_compte = p_destination;

    COMMIT;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END;
$$;
```

